<?php require 'config.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$stmt=$pdo->prepare('SELECT * FROM tours WHERE id=? AND active=1');$stmt->execute([$id]);$tour=$stmt->fetch();if(!$tour){http_response_code(404);exit('Tour not found');}require 'header.php';?><section class="page-head"><a href="tours.php">← All Tours</a><h1><?=e($tour['title'])?></h1><p><?=e($tour['location'])?></p></section><div class="panel"><div class="emoji">⛰️</div><p><?=e($tour['description'])?></p><p><strong><?=e($tour['price'])?> SAR</strong> per visitor</p><p>Available seats per date: <?=e($tour['capacity'])?></p><a class="btn" href="book.php?id=<?=$tour['id']?>">Book This Tour</a></div><?php require 'footer.php';?>